content.text:
The incident is a CPU saturation fault in `ts-payment-service`. Its CPU spiked, its calls slowed, and the failures propagated up through `ts-inside-payment-service` to `ts-ui-dashboard`.

```json
{
  "root_causes": [
    {
      "service": "ts-payment-service",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT strftime(time,'%H:%M') t, round(avg(value),3) cpu_cores, round(max(value),3) max_cores FROM abnormal_metrics WHERE service_name='ts-payment-service' AND metric='container.cpu.usage' GROUP BY 1 ORDER BY 1",
          "claim": "Payment container CPU jumps to about 1.26 cores at 15:38 (max 3.9) versus about 0.01 cores in normal operation."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'normal' p, round(avg(value),3) avg_cpu, round(max(value),3) max_cpu FROM normal_metrics WHERE service_name='ts-payment-service' AND metric='container.cpu.usage' UNION ALL SELECT 'abnormal', round(avg(value),3), round(max(value),3) FROM abnormal_metrics WHERE service_name='ts-payment-service' AND metric='container.cpu.usage'",
          "claim": "Payment container CPU averages 0.012 cores normally and 0.456 cores during the incident."
        },
        {
          "kind": "trace",
          "sql": "SELECT strftime(time,'%H:%M') t, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-payment-service' AND attr_span_kind='Server' GROUP BY 1 ORDER BY 1",
          "claim": "Payment server spans slow to about 1.1s at 15:38 and their volume collapses from 270 normal spans to 115 abnormal."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.attr_http_response_status_code code, s.service_name child_service, count(*) n, round(avg(c.duration)/1e6,1) client_ms FROM abnormal_traces c LEFT JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.trace_id = c.trace_id AND s.attr_span_kind='Server' WHERE c.service_name='ts-inside-payment-service' AND c.attr_span_kind='Client' AND c.span_name='POST' GROUP BY ALL ORDER BY 1",
          "claim": "Inside-payment's POST calls to payment take 1.26s on success and 503 after 3.5s with no payment span on failure."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-payment-service",
      "to": "ts-inside-payment-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,1) avg_ms, sum(CASE WHEN attr_http_response_status_code>=500 THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-inside-payment-service' AND span_name='POST /api/v1/inside_pay_service/inside_payment' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "Inside-payment's payment endpoint returns 500 on 8 of 15 requests with roughly 2.5s average latency, versus 55ms normally."
        }
      ]
    },
    {
      "from": "ts-inside-payment-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, count(*) n, round(avg(duration)/1e6,1) avg_ms, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='POST /api/v1/inside_pay_service/inside_payment' AND attr_span_kind='Server' GROUP BY 1",
          "claim": "The user-facing dashboard's inside_payment endpoint shows multi-second latency during the incident, caused by the downstream inside-payment failures."
        }
      ]
    }
  ]
}
```
